param([ValidateSet('Initialize','Step','Missing','Cleanup')][string]$Phase)
$ErrorActionPreference='Stop';$inputData=[Console]::In.ReadToEnd()|ConvertFrom-Json;$taskRoot=Split-Path $PSScriptRoot -Parent
if($inputData.id -cnotmatch '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'){throw 'Invalid owned agent fixture identity'}
$directory='C:\ProgramData\CormierDnsManager\RecoveryAgentAcceptance-'+$inputData.id;$session=New-PSSession -ComputerName domain02.cormierconsulting.com
try{
 if($Phase -eq 'Initialize'){
  Invoke-Command -Session $session -ArgumentList $directory -ScriptBlock {param($directory);$ErrorActionPreference='Stop';if(Test-Path -LiteralPath $directory){throw 'Owned agent directory already exists'};New-Item -ItemType Directory -Path $directory|Out-Null;[IO.File]::WriteAllText((Join-Path $directory 'owner.txt'),[IO.Path]::GetFileName($directory));foreach($name in @('channel','bridge')){$private=Join-Path $directory $name;New-Item -ItemType Directory -Path $private|Out-Null;& icacls $private /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F'|Out-Null;if($LASTEXITCODE -ne 0){throw 'Private agent fixture permissions failed'}}}
  $hashes=@{};foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1','windows-dns-bridge.ps1')){$source=Join-Path $taskRoot ('live-management/'+$name);$target=if($name -eq 'windows-dns-bridge.ps1'){'bridge'}else{'channel'};Copy-Item -LiteralPath $source -Destination ($directory+'\'+$target+'\'+$name) -ToSession $session;$hashes[$name]=(Get-FileHash -LiteralPath $source).Hash}
  $result=Invoke-Command -Session $session -ArgumentList $directory,$inputData,$hashes -ScriptBlock {
   param($directory,$inputData,$hashes);$ErrorActionPreference='Stop';$channel=Join-Path $directory 'channel';$bridge=Join-Path $directory 'bridge';foreach($name in $hashes.Keys){$target=if($name -eq 'windows-dns-bridge.ps1'){$bridge}else{$channel};if((Get-FileHash -LiteralPath (Join-Path $target $name)).Hash -cne $hashes[$name]){throw 'Transferred agent source differs'}}
   foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1')){. (Join-Path $channel $name)}
   $installed=Get-Content -LiteralPath 'C:\ProgramData\CormierDnsManager\configuration.json' -Raw|ConvertFrom-Json
   $preserved=@{configuration=(Get-FileHash -LiteralPath 'C:\ProgramData\CormierDnsManager\configuration.json').Hash;kubeconfig=(Get-FileHash -LiteralPath $installed.kubeconfig).Hash;bridge=(Get-FileHash -LiteralPath 'C:\ProgramData\CormierDnsManager\windows-dns-bridge.ps1').Hash};[IO.File]::WriteAllText((Join-Path $directory 'preserved.json'),($preserved|ConvertTo-Json -Compress))
   $settings=[pscustomobject]@{version=1;namespace=$inputData.namespace;clusterUid=$inputData.clusterUid;accountUid=$inputData.accountUid;agentAccountUid=$inputData.agentAccountUid;requestUid=$inputData.requestUid;receiptUid=$inputData.receiptUid;channelRoot=$channel;bridgeRoot=$bridge;kubectl=$installed.kubectl;clusterCaData=$inputData.clusterCaData;bridgeSourceDigest=$hashes['windows-dns-bridge.ps1'].ToLowerInvariant()}
   function Config([string]$token){return @{apiVersion='v1';kind='Config';clusters=@(@{name='cluster';cluster=@{server='https://10.99.15.50:6443';'tls-server-name'='kubernetes.cormierconsulting.io';'certificate-authority-data'=$settings.clusterCaData}});users=@(@{name='bridge';user=@{token=$token}});contexts=@(@{name='bridge';context=@{cluster='cluster';user='bridge';namespace='dns-system'}});'current-context'='bridge'}|ConvertTo-Json -Depth 10 -Compress}
   Write-DnsRecoveryFile (Join-Path $channel 'agent.json') ([Text.Encoding]::UTF8.GetBytes(($settings|ConvertTo-Json -Depth 6 -Compress)));Write-DnsRecoveryFile (Join-Path $channel 'recovery-kubeconfig.json') ([Text.Encoding]::UTF8.GetBytes((Config $inputData.agentToken)));Write-DnsRecoveryFile (Join-Path $bridge 'kubeconfig.json') ([Text.Encoding]::UTF8.GetBytes((Config 'broken.local.signature')))
   $null=Assert-DnsRecoveryAgentSettings $settings;if(Confirm-DnsRecoveryIdentity $settings (Join-Path $bridge 'kubeconfig.json') 'dns-windows-bridge' $settings.accountUid){throw 'Broken bridge fixture unexpectedly authenticated'};if(!(Confirm-DnsRecoveryIdentity $settings (Join-Path $channel 'recovery-kubeconfig.json') 'dns-windows-recovery-agent' $settings.agentAccountUid)){throw 'Independent fixture identity did not authenticate'}
   @{directory=$directory;key=(New-DnsRecoveryChannelKey $channel);sourceHashes=$hashes;brokenBridgeRejected=$true;independentIdentityAuthenticated=$true}|ConvertTo-Json -Depth 8
  };$result
 }elseif($Phase -eq 'Step'){
  Invoke-Command -Session $session -ArgumentList $directory,$inputData -ScriptBlock {
   param($directory,$inputData);$ErrorActionPreference='Stop';$channel=Join-Path $directory 'channel';foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1')){. (Join-Path $channel $name)};$settings=Get-Content -LiteralPath (Join-Path $channel 'agent.json') -Raw|ConvertFrom-Json
   $script:writes=0;$writer=[Management.Automation.Language.Parser]::ParseFile((Join-Path $channel 'windows-dns-credential-recovery.ps1'),[ref]$null,[ref]$null).Find({param($node);$node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -eq 'Write-DnsRecoveryFile'},$true);Invoke-Expression ($writer.Extent.Text.Replace('function Write-DnsRecoveryFile','function Write-OriginalDnsRecoveryFile'));function Write-DnsRecoveryFile([string]$Path,[byte[]]$Bytes){if([IO.Path]::GetFileName($Path) -eq 'kubeconfig.json'){$script:writes++};Write-OriginalDnsRecoveryFile $Path $Bytes}
   $stamp=if(Test-Path -LiteralPath (Join-Path $settings.bridgeRoot 'kubeconfig.json')){(Get-Item -LiteralPath (Join-Path $settings.bridgeRoot 'kubeconfig.json')).LastWriteTimeUtc.Ticks}else{$null}
   $outcome=Invoke-DnsRecoveryAgentIteration $settings -Now $inputData.now
   $json=$outcome|ConvertTo-Json -Compress;if($json.Contains('token') -or $json.Contains('certificate-authority-data')){throw 'Recovery outcome exposed credentials'}
   @{outcome=$outcome;credentialWrites=$script:writes;stampBefore=$stamp;stampAfter=if(Test-Path -LiteralPath (Join-Path $settings.bridgeRoot 'kubeconfig.json')){(Get-Item -LiteralPath (Join-Path $settings.bridgeRoot 'kubeconfig.json')).LastWriteTimeUtc.Ticks}else{$null};leasePresent=(Test-Path -LiteralPath (Join-Path $settings.bridgeRoot 'credential-recovery-active.json'))}|ConvertTo-Json -Depth 8
  }
 }elseif($Phase -eq 'Missing'){
  Invoke-Command -Session $session -ArgumentList $directory -ScriptBlock {param($directory);$ErrorActionPreference='Stop';if([IO.File]::ReadAllText((Join-Path $directory 'owner.txt')) -cne [IO.Path]::GetFileName($directory)){throw 'Fixture ownership differs'};$path=Join-Path $directory 'bridge/kubeconfig.json';if((Get-Item -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Unsafe fixture credential path'};[IO.File]::Delete($path);@{missing=!(Test-Path -LiteralPath $path)}|ConvertTo-Json}
 }else{
  Invoke-Command -Session $session -ArgumentList $directory -ScriptBlock {
   param($directory);$ErrorActionPreference='Stop';$resolved=[IO.Path]::GetFullPath($directory);$parent=[IO.Path]::GetFullPath('C:\ProgramData\CormierDnsManager').TrimEnd('\')+'\';if(!$resolved.StartsWith($parent,[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetFileName($resolved) -notmatch '^RecoveryAgentAcceptance-[0-9a-f-]{36}$'){throw 'Owned cleanup target differs'}
   if(Test-Path -LiteralPath $resolved){if([IO.File]::ReadAllText((Join-Path $resolved 'owner.txt')) -cne [IO.Path]::GetFileName($resolved)){throw 'Fixture ownership differs'};$baseline=Get-Content -LiteralPath (Join-Path $resolved 'preserved.json') -Raw|ConvertFrom-Json;$installed=Get-Content -LiteralPath 'C:\ProgramData\CormierDnsManager\configuration.json' -Raw|ConvertFrom-Json;$current=@{configuration=(Get-FileHash -LiteralPath 'C:\ProgramData\CormierDnsManager\configuration.json').Hash;kubeconfig=(Get-FileHash -LiteralPath $installed.kubeconfig).Hash;bridge=(Get-FileHash -LiteralPath 'C:\ProgramData\CormierDnsManager\windows-dns-bridge.ps1').Hash};foreach($key in $current.Keys){if($current[$key] -cne $baseline.$key){throw 'Installed bridge files changed'}};if((Get-ScheduledTask -TaskName 'Cormier DNS Manager Bridge').State -ne 'Running'){throw 'Installed bridge is not running'};Remove-Item -LiteralPath $resolved -Recurse -Force};@{ownedDirectoryRemoved=!(Test-Path -LiteralPath $resolved);installedBridgePreserved=$true}|ConvertTo-Json
  }
 }
}finally{Remove-PSSession $session}
